    15	 * 2. Development Mode (AUTH_DEV_MODE=true): Allows skipping verification using x-customer-id header
    16	 */
    17	function authMiddleware(req, res, next) {
    18	  // Development mode: Allow x-customer-id header
    19	  if (config.auth.devMode) {
    20	    const customerId = req.headers['x-customer-id'];
    21	    if (customerId) {
    22	      req.customerId = customerId;
    23	      req.isDevMode = true;
    24	      return next();
    25	    }
    26	  }
    27	
    28	  // Get Authorization header
    29	  const authHeader = req.headers.authorization;
    30	  
    31	  // Extract token
    32	  const token = extractTokenFromHeader(authHeader);
    33	  
    34	  if (!token) {
    35	    // If in development mode and no token provided, use default user ID
